-- public.institution_draft_run_refusals(p_institution_id uuid, p_apply_id uuid)
CREATE OR REPLACE FUNCTION public.institution_draft_run_refusals(p_institution_id uuid, p_apply_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v public.institution_draft_runs;
begin
  -- HD-3a-F1 R-7-2: after «übernehmen» the screen reads the refused rows of this run back from its record (T-1: shown =
  -- saved answer), so it can name the person whose row was refused for a missing Pensum. Only the apply id travels in
  -- the URL, never a name. A member of the home (lead, planner) reads only a run of this home; LEAVE1-3 through the
  -- membership check (an ended access is nobody's member). Read only, no audit (as institution_plan).
  if p_institution_id is null or p_apply_id is null
     or not private.is_institution_member(p_institution_id, array['lead', 'planner']) then
    return jsonb_build_object('result', 'rejected');
  end if;
  select * into v from public.institution_draft_runs where id = p_apply_id and institution_id = p_institution_id;
  if v.id is null then
    return jsonb_build_object('result', 'not_found');
  end if;
  return jsonb_build_object('result', 'ok', 'applied', v.rows_applied,
    'refused', coalesce((select jsonb_agg(jsonb_build_object('staff_id', x ->> 'staff_id', 'date', x ->> 'date',
                                                            'shift_type_id', x ->> 'shift_type_id', 'reason', x ->> 'reason')
                                          order by x ->> 'date', x ->> 'staff_id')
                         from jsonb_array_elements(v.refused) x), '[]'::jsonb));
end $function$;

